const productName = items[0].json.productName;
const sheetData = items[1].json;

const product = sheetData.find(
  row => row['Product Name'] && row['Product Name'].toLowerCase() === productName.toLowerCase()
);

if (!product) {
  throw new Error(`Product not found: ${productName}`);
}

return [{
  json: {
    productName: product['Product Name'],
    productImageUrl: product['Product Image URL'],
    productId: product['Product ID'],
    customerImage: items[0].json.customerImage,
    email: items[0].json.email,
    callbackUrl: items[0].json.callbackUrl
  }
}];

