const response = items[0].json;

try {
  if (!response.candidates || response.candidates.length === 0) {
    throw new Error('No candidates in Gemini response');
  }

  const imageBase64 = response.candidates[0].content.parts[0].text;

  return [{
    json: {
      imageBase64: imageBase64,
      timestamp: new Date().toISOString(),
      productName: items[0].json.productName
    }
  }];
} catch (error) {
  throw new Error(`Failed to parse Gemini response: ${error.message}`);
}

const fileId = items[0].json.id;

return [{
  json: {
    downloadUrl: `https://drive.google.com/file/d/${fileId}/view?usp=sharing`,
    fileId: fileId,
    timestamp: items[0].json.timestamp
  }
}];
